mapper.update:
UPDATE inventory
SET quantity = quantity + #{quantity},
    location_code = COALESCE(#{locationCode}, location_code),
    updated_by = #{updatedBy}
WHERE id = #{id}
  AND deleted = 0

mapper.select:
SELECT i.id, i.drug_id, d.drug_code, d.drug_name, i.batch_no, i.expiry_date, i.quantity, i.locked_quantity, i.location_code, i.created_at, i.updated_at FROM inventory i INNER JOIN drug d ON d.id = i.drug_id WHERE i.deleted = 0 AND d.deleted = 0
AND i.drug_id = #{drugId}
AND ( d.drug_code LIKE CONCAT('%', #{keyword}, '%') OR d.drug_name LIKE CONCAT('%', #{keyword}, '%') OR i.batch_no LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY i.updated_at DESC, i.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(1) FROM inventory i INNER JOIN drug d ON d.id = i.drug_id WHERE i.deleted = 0 AND d.deleted = 0
AND i.drug_id = #{drugId}
AND ( d.drug_code LIKE CONCAT('%', #{keyword}, '%') OR d.drug_name LIKE CONCAT('%', #{keyword}, '%') OR i.batch_no LIKE CONCAT('%', #{keyword}, '%') )
